define('taoClientDiagnostic/tools/csvExporter',['jquery', 'lodash', 'i18n', 'core/request', 'layout/loading-bar', 'helpers'], function ($, _, __, request, loadingBar, helpers) {
  'use strict';
  var cssScope = '.diagnostic-index';
  return {
    exportCsv(model) {
      var $container = $(cssScope);
      var extension = $container.data('extension') || 'taoClientDiagnostic';
      var serviceUrl = helpers._url('diagnosticData', 'Diagnostic', extension);
      function mappingDiagnosticsData(diagnostics) {
        return diagnostics.map(diagnostic => {
          var result = {};
          _.forEach(model, field => {
            result[field.id] = field.transform ? field.transform(diagnostic[field.id], diagnostic) : diagnostic[field.id];
          });
          return result;
        });
      }
      function arrayToCsv(data) {
        var columnDelimiter = arguments.length > 1 && arguments[1] !== undefined ? arguments[1] : ',';
        var lineDelimiter = arguments.length > 2 && arguments[2] !== undefined ? arguments[2] : '\n';
        var keys = Object.keys(data[0]);
        var result = "".concat(keys.join(columnDelimiter)).concat(lineDelimiter);
        data.forEach(item => {
          var ctr = 0;
          keys.forEach(key => {
            if (ctr > 0) {
              result += columnDelimiter;
            }
            result += typeof item[key] === 'string' && item[key].includes(columnDelimiter) ? "\"".concat(item[key], "\"") : item[key];
            ctr++;
          });
          result += lineDelimiter;
        });
        return result;
      }
      function downloadFile(content, filename, type) {
        var blob = new Blob([content], {
          type: type
        });
        var url = URL.createObjectURL(blob);
        var link = $('<a></a>');
        link.attr('download', filename).attr('href', url).get(0).click();
        URL.revokeObjectURL(url);
        link = null;
      }
      loadingBar.start();
      request({
        url: serviceUrl,
        data: {
          rows: Number.MAX_SAFE_INTEGER
        },
        noToken: true
      }).then(response => {
        var mappedData = mappingDiagnosticsData(response.data);
        var csvContent = arrayToCsv(mappedData);
        downloadFile(csvContent, __('diagnostics.csv'), 'text/csv');
        loadingBar.stop();
      }).catch(() => {
        loadingBar.stop();
      });
    }
  };
});
