          bandwidthMin: {
            message: labels.bandwidthMin,
            value: results.min + ' Mbps'
          },
          bandwidthMax: {
            message: labels.bandwidthMax,
            value: results.max + ' Mbps'
          },
          bandwidthAverage: {
            message: labels.bandwidthAverage,
            value: results.average + ' Mbps'
          }
