        var status = getStatus(baseBandwidth / max * 100, initConfig.feedbackThresholds, getStatusOptions);
        var nb = Math.floor(baseBandwidth / bandwidthUnit);
        if (nb > maxTestTakers) {
          nb = '>' + maxTestTakers;
        }
        status.id = initConfig.id;
        status.title = labels.title;
        status.feedback.legend = labels.legend;
        status.quality.label = nb;
