define('taoClientDiagnostic/controller/Diagnostic/index',['jquery', 'lodash', 'i18n', 'helpers', 'moment', 'core/request', 'layout/loading-bar', 'util/encode', 'ui/feedback', 'ui/dialog', 'taoClientDiagnostic/tools/getStatus', 'taoClientDiagnostic/tools/performances/tester', 'taoClientDiagnostic/tools/fingerprint/tester', 'tpl!taoClientDiagnostic/tools/diagnostic/tpl/fingerprint', 'tpl!taoClientDiagnostic/tools/diagnostic/tpl/details', 'taoClientDiagnostic/tools/csvExporter', 'ui/datatable', 'lib/moment-timezone.min'], function ($, _, __, helpers, moment, request, loadingBar, encode, feedback, dialog, getStatus, performancesTesterFactory, fingerprintTesterFactory, fingerprintTpl, detailsTpl, csvExporter) {
  'use strict';
  var cssScope = '.diagnostic-index';
  var defaultDateTimeZone = 'UTC';
  var defaultDateFormat = 'Y/MM/DD HH:mm:ss';
  function formatNumber(value, digits) {
    var nb = 'undefined' === typeof digits ? 2 : Math.max(0, parseInt(digits, 10));
    var factor = Math.pow(10, nb) || 1;
    return Math.round(value * factor) / factor;
  }
  function formatBandwidth(value) {
    if (value > 100) {
      return '> 100';
    }
    return formatNumber(value);
  }
  function transformDateToLocal(date) {
    var time;
    if (_.isFinite(date)) {
      if (!_.isNumber(date)) {
        date = _.parseInt(date, 10);
      }
      var d = new Date(date * 1000);
      time = moment.utc(d);
    } else {
      time = moment.tz(date, defaultDateTimeZone);
    }
    return time.tz(moment.tz.guess()).format(defaultDateFormat);
  }
  loadingBar.start();
  return {
    start() {
      var $container = $(cssScope);
      var extension = $container.data('extension') || 'taoClientDiagnostic';
      var $list = $container.find('.list');
      var dataset = $container.data('set');
      var extensionConfig = $container.data('config') || {};
      var config = extensionConfig.diagnostic || extensionConfig;
      var installedExtension = $container.data('installedextension') || false;
      var diagnosticUrl = helpers._url('diagnostic', 'Diagnostic', extension);
      var removeUrl = helpers._url('remove', 'Diagnostic', extension);
      var serviceUrl = helpers._url('diagnosticData', 'Diagnostic', extension);
      var performancesTester = performancesTesterFactory(config.testers.performance || {});
      var fingerprintTester = fingerprintTesterFactory(config.testers.fingerprint || {});
      var tools = [];
      var actions = [];
      var model = [];
      function requestData(url, selection, message) {
        if (selection && selection.length) {
          loadingBar.start();
          request({
            url,
            data: {
              id: selection
            },
            method: 'POST',
            noToken: true
          }).then(response => {
            loadingBar.stop();
            if (response && response.success) {
              if (message) {
                feedback().success(message);
              }
              $list.datatable('refresh');
            } else {
              feedback().error("".concat(__('Something went wrong ...'), "<br>").concat(encode.html(response.error)), {
                encodeHtml: false
              });
            }
          }).catch(() => loadingBar.stop());
        }
      }
      function remove(selection) {
        requestData(removeUrl, selection, __('The readiness check result have been removed'));
      }
      tools.push({
        id: 'refresh',
        icon: 'reset',
        title: __('Refresh the page'),
        label: __('Refresh'),
        action() {
          $list.datatable('refresh');
        }
      });
      tools.push({
        id: 'launch',
        icon: 'play',
        title: __('Launch another readiness check'),
        label: __('Launch readiness check'),
        action() {
          window.location.href = diagnosticUrl;
        }
      });
      if (config.export) {
        tools.push({
          id: 'csvExport',
          icon: 'export',
          title: __('Export CSV'),
          label: __('Export CSV'),
          action() {
            csvExporter.exportCsv(model);
          }
        });
      }
      if (installedExtension) {
        tools.push({
          id: 'lti',
          icon: 'play',
          title: __('Try a test delivery'),
          label: __('Try a test delivery'),
          action() {
            window.location.href = deliveryUrl;
          }
        });
      }
      tools.push({
        id: 'remove',
        icon: 'remove',
        title: __('Remove the selected readiness check results'),
        label: __('Remove'),
        massAction: true,
        action(selection) {
          dialog({
            message: __('The selected readiness check results will be removed. Continue ?'),
            autoRender: true,
            autoDestroy: true,
            onOkBtn() {
              remove(selection);
            }
          });
        }
      });
      if (window.self === window.top) {
        tools.push({
          id: 'exitButton',
          icon: 'close',
          title: __('Exit'),
          label: __('Exit'),
          action() {
            window.self.close();
          }
        });
      }
      actions.push({
        id: 'remove',
        icon: 'remove',
        title: __('Remove the readiness check result?'),
        action(id) {
          dialog({
            autoRender: true,
            autoDestroy: true,
            message: __('The readiness check result will be removed. Continue ?'),
            onOkBtn() {
              remove([id]);
            }
          });
        }
      });
      model.push({
        id: 'workstation',
        label: __('Workstation')
      });
      if (config.requireSchoolName) {
        model.push({
          id: 'school_name',
          label: __('School name')
        });
      }
      if (config.requireSchoolId) {
        model.push({
          id: 'school_id',
          label: __('School id')
        });
      }
      if (config.validateSchoolName) {
        model.push({
          id: 'school_number',
          label: __('School number')
        });
      }
      if (config.testers.fingerprint && config.testers.fingerprint.enabled) {
        model.push({
          id: 'fingerprint-cell',
          label: __('Fingerprint'),
          transform(v, row) {
            return fingerprintTpl(row.fingerprint);
          }
        });
        $list.on('click.fingerprint', '.fingerprint-cell span.details', function (e) {
          var id = $(e.target).closest('tr').data('itemIdentifier');
          var row = _.find(dataset.data, {
            id: id
          });
          if (row) {
            dialog({
              content: detailsTpl(fingerprintTester.getSummary(row.fingerprint)),
              buttons: 'ok',
              autoRender: true,
              autoDestroy: true
            });
          }
        });
      }
      if (config.testers.screen && config.testers.screen.enabled) {
        model.push({
          id: 'screen_size',
          label: __('Screen resolution'),
          transform(value, row) {
            if (row.screen && row.screen.width && row.screen.height) {
              return row.screen.width + 'x' + row.screen.height;
            }
          }
        });
      }
      if (config.testers.browser && config.testers.browser.enabled) {
        model.push({
          id: 'os',
          label: __('OS')
        });
        model.push({
          id: 'browser',
          label: __('Browser')
        });
      }
      if (config.testers.performance && config.testers.performance.enabled) {
        model.push({
          id: 'performance',
          label: __('Performances'),
          transform(value) {
            var status = performancesTester.getFeedback(value);
            return status.feedback && status.feedback.message;
          }
        });
      }
      if (config.testers.bandwidth && config.testers.bandwidth.enabled) {
        model.push({
          id: 'bandwidth',
          label: __('Bandwidth'),
          transform: formatBandwidth
        });
      }
      if (config.testers.intensive_bandwidth && config.testers.intensive_bandwidth.enabled) {
        model.push({
          id: 'intensive_bandwidth',
          label: __('Intensive bandwidth'),
          transform: formatBandwidth
        });
      }
      if (config.testers.upload && config.testers.upload.enabled) {
        model.push({
          id: 'upload',
          label: __('Upload speed'),
          transform: formatBandwidth
        });
      }
      model.push({
        id: 'date',
        label: __('Date'),
        transform: transformDateToLocal
      });
      $list.on('query.datatable', () => loadingBar.start()).on('load.datatable', (e, data) => {
        dataset = data;
        loadingBar.stop();
      }).datatable({
        url: serviceUrl,
        status: {
          empty: __('No readiness checks have been done!'),
          available: __('Readiness checks already done'),
          loading: __('Loading')
        },
        selectable: true,
        tools,
        actions,
        model
      }, dataset);
    }
  };
});
