define('taoClientDiagnostic/controller/Diagnostic/diagnostic',['module', 'jquery', 'i18n', 'helpers', 'core/request', 'layout/loading-bar', 'ui/actionbar', 'ui/feedback', 'taoClientDiagnostic/tools/diagnostic/diagnostic', 'tpl!taoClientDiagnostic/templates/diagnostic/main'], function (module, $, __, helpers, request, loadingBar, actionbar, feedback, diagnosticFactory, diagnosticTpl) {
  'use strict';
  var cssScope = '.diagnostic-runner';
  loadingBar.start();
  return {
    start() {
      var $container = $(cssScope);
      var extension = $container.data('extension') || 'taoClientDiagnostic';
      var $list = $container.find('.list');
      var $panel = $('.panel');
      var extensionConfig = $container.data('config') || {};
      var config = extensionConfig.diagnostic || extensionConfig;
      var indexUrl = helpers._url('index', 'Diagnostic', extension);
      var buttons = [];
      var moduleConfig = module.config() || {};
      config.configurableText = moduleConfig.configurableText || {};
      function installTester(workstation) {
        diagnosticFactory($list, config).setTemplate(diagnosticTpl).on('render', function onDiagnosticRender() {
          this.controls.$workstation = this.getElement().find('[data-control="workstation"]').on('keypress', e => {
            if (e.which === 13) {
              e.preventDefault();
              this.run();
            }
          }).val(workstation);
          loadingBar.stop();
          if (config.autoStart) {
            this.run();
          }
        }).on('start', function onDiagnosticStart() {
          this.config.storeParams = this.config.storeParams || {};
          this.config.storeParams.workstation = this.controls.$workstation.val();
          this.controls.$workstation.prop('disabled', true);
          loadingBar.start();
        }).on('end', function onDiagnosticEnd() {
          this.controls.$workstation.prop('disabled', false);
          loadingBar.stop();
        });
      }
      buttons.push({
        id: 'back',
        icon: 'step-backward',
        title: __('Return to the list'),
        label: __('List of readiness checks'),
        action() {
          window.location.href = indexUrl;
        }
      });
      if (window.self === window.top) {
        buttons.push({
          id: 'exitButton',
          icon: 'close',
          title: __('Exit'),
          label: __('Exit'),
          action() {
            window.self.close();
          }
        });
      }
      actionbar({
        renderTo: $panel,
        buttons
      });
      var url = helpers._url('workstation', 'DiagnosticChecker', extension);
      request({
        url,
        noToken: true
      }).then(data => installTester(data && data.workstation)).catch(() => {
        feedback().error(__('Unable to get the workstation name!'));
        installTester();
      });
    }
  };
});
